doc = json.loads(DATA)
els = doc["elements"]
by_id = {e["id"]: e for e in els}

# --- Fix 1: split the (incorrect) shared FC head into two model-specific heads ---
tr = by_id["Bfc"]                       # template rectangle (old shared head)
tt = by_id["0CQycZaCaIvp1HEk7f1Qc"]     # its bound text

def make_head(rid, tid, x, w, label, ridx, tidx):
    r = copy.deepcopy(tr)
    r.update({"id": rid, "x": x, "y": 537, "width": w, "height": 66,
              "index": ridx, "boundElements": [{"type": "text", "id": tid}]})
    t = copy.deepcopy(tt)
    t.update({"id": tid, "containerId": rid, "text": label, "originalText": label,
              "x": x + 14, "y": 552, "width": w - 28, "index": tidx})
    return r, t

cnn_r, cnn_t = make_head("Bfc_cnn", "Bfc_cnn_t", 441, 162,
                         "FC head (1D-CNN)\n256->64->4, Drop 0.4", "c00", "c01")
lstm_r, lstm_t = make_head("Bfc_lstm", "Bfc_lstm_t", 607, 162,
                           "FC head (ConvLSTM)\n128->64->4, Drop 0.4", "c02", "c03")

# --- Fix 2: make the branch -> head arrows straight (each feeds only its own head) ---
for aid in ("amrgl", "amrgr"):
    by_id[aid]["points"] = [[0, 0], [0, 57]]
    by_id[aid]["width"] = 0
    by_id[aid]["height"] = 57

# --- Fix 3: two converging arrows from the two heads into the Training box ---
atpl = by_id["abc3"]                     # simple arrow template (null bindings)

def make_arrow(aid, x, y, pts, idx):
    a = copy.deepcopy(atpl)
    a.update({"id": aid, "x": x, "y": y, "points": pts, "index": idx,
              "boundElements": [],
              "width": max(abs(p[0]) for p in pts),
              "height": max(abs(p[1]) for p in pts)})
    return a

arr_cnn = make_arrow("abtrain_cnn", 522, 603, [[0, 0], [83, 42]], "c04")
arr_lstm = make_arrow("abtrain_lstm", 688, 603, [[0, 0], [-83, 42]], "c05")

# --- Fix 4: correct the spectral-feedback label ---
sl = by_id["HbvmbtFNRM3xn_KXRkON7"]
sl["text"] = "+0.1*L_spectral"
sl["originalText"] = "+0.1*L_spectral"
